// Generated by exit-ramp. A Val Town std/blob-shaped facade over Cloudflare R2 (binding: BLOB).
//
// Matches: get (returns a Response), getJSON (undefined when missing), set, setJSON, delete, list(prefix), copy, move.
// Differences: R2 is object storage, not the Val Town blob store. list() returns { key, size, lastModified (ISO string) }.
// copy/move buffer the object in memory (fine for small blobs). Private data stays private: nothing here makes an object public.
import { env } from "cloudflare:workers";

export class BlobNotFoundError extends Error {
  override name = "BlobNotFoundError";
}

const bucket = (): R2Bucket => {
  const b = (env as unknown as { BLOB?: R2Bucket }).BLOB;
  if (!b) throw new Error('No R2 binding named "BLOB". Add an [[r2_buckets]] entry to wrangler.toml.');
  return b;
};

export interface BlobListItem {
  key: string;
  size: number;
  lastModified: string;
}

async function toR2Value(value: string | BodyInit): Promise<string | ArrayBuffer | ArrayBufferView | Blob> {
  if (typeof value === "string" || value instanceof ArrayBuffer || ArrayBuffer.isView(value) || value instanceof Blob) return value;
  // streams without a known length cannot be written to R2 directly: buffer them
  return await new Response(value).arrayBuffer();
}

export const blob = {
  async get(key: string): Promise<Response> {
    const obj = await bucket().get(key);
    if (!obj) throw new BlobNotFoundError(`Blob not found: ${key}`);
    const headers = new Headers();
    const m = obj.httpMetadata;
    if (m?.contentType) headers.set("content-type", m.contentType);
    if (m?.contentLanguage) headers.set("content-language", m.contentLanguage);
    if (m?.contentDisposition) headers.set("content-disposition", m.contentDisposition);
    if (m?.contentEncoding) headers.set("content-encoding", m.contentEncoding);
    if (m?.cacheControl) headers.set("cache-control", m.cacheControl);
    headers.set("etag", obj.httpEtag);
    return new Response(obj.body, { headers });
  },

  async getJSON<T = unknown>(key: string): Promise<T | undefined> {
    const obj = await bucket().get(key);
    if (!obj) return undefined;
    return (await obj.json()) as T;
  },

  async set(key: string, value: string | BodyInit): Promise<void> {
    await bucket().put(key, await toR2Value(value));
  },

  async setJSON(key: string, value: unknown): Promise<void> {
    await bucket().put(key, JSON.stringify(value), { httpMetadata: { contentType: "application/json" } });
  },

  async delete(key: string): Promise<void> {
    await bucket().delete(key);
  },

  async list(prefix?: string): Promise<BlobListItem[]> {
    const out: BlobListItem[] = [];
    let cursor: string | undefined;
    for (;;) {
      const page = await bucket().list({ prefix, cursor });
      for (const o of page.objects) out.push({ key: o.key, size: o.size, lastModified: o.uploaded.toISOString() });
      if (!page.truncated) break;
      cursor = page.cursor;
    }
    return out;
  },

  async copy(previous: string, next: string): Promise<void> {
    const obj = await bucket().get(previous);
    if (!obj) throw new BlobNotFoundError(`Blob not found: ${previous}`);
    await bucket().put(next, await obj.arrayBuffer(), { httpMetadata: obj.httpMetadata, customMetadata: obj.customMetadata });
  },

  async move(previous: string, next: string): Promise<void> {
    await blob.copy(previous, next);
    await bucket().delete(previous);
  },
};
